        if assert_fingerprint:
            _assert_fingerprint(ssl_sock.getpeercert(binary_form=True), assert_fingerprint)
        elif (context.verify_mode != ssl.CERT_NONE and not context.check_hostname and assert_hostname is not False):
            cert: _TYPE_PEER_CERT_RET_DICT = ssl_sock.getpeercert()
            if default_ssl_context:
                hostname_checks_common_name = False
            else:
                hostname_checks_common_name = (getattr(context, 'hostname_checks_common_name', False) or False)
            _match_hostname(cert, (assert_hostname or server_hostname), hostname_checks_common_name)
        return _WrappedAndVerifiedSocket(socket=ssl_sock, is_verified=(context.verify_mode == ssl.CERT_REQUIRED or bool(assert_fingerprint)))
    except BaseException:
        ssl_sock.close()
        raise

urllib3.contrib.emscripten.fetch._show_s:
def _show_streaming_warning() -> None:
    global _SHOWN_STREAMING_WARNING
    if not _SHOWN_STREAMING_WARNING:
        _SHOWN_STREAMING_WARNING = True
        message = "Can't stream HTTP requests because: \n"
        if not is_cross_origin_isolated():
            message += '  Page is not cross-origin isolated\n'
        if is_in_browser_main_thread():
            message += '  Python is running in main browser thread\n'
        if not is_worker_available():
            message += ' Worker or Blob classes are not available in this environment.'
        if streaming_ready() is False:
            message += " Streaming fetch worker isn't ready. If you want to be sure that streaming fetch\nis working, you need to call: 'await urllib3.contrib.emscripten.fetch.wait_for_streaming_ready()`"
        from js import console
        console.warn(message)

